style.css:
@-moz-document url-prefix("https://www.jeuxvideo.com/forums/") {
.avatar__image {
        border-radius: 0.5rem;
    }
    
    .postMessage {
        border-radius: 0.5rem;
    }
    
    .messageEditor__groupSelector {
        border-radius: 0.5rem !important;
    }

    .cancelMessage {
        border-radius: 0.5rem;
        margin-bottom: 16px;
    }
    
    .avatar--moderator {
        --shadow-color: none;
        border-radius: 0.5rem;
        background-color: #42b228;
        ;
    }
    
    .avatar--admin {
        --shadow-color: none;
        border-radius: 0.5rem;
        background-color: #f24444;
        ;
    }
}
